<script setup>
import {notify} from '../notifications.js';
import {ref,onMounted} from 'vue';import {requestJson} from '../api.js';
const props=defineProps({serviceId:String,remove:Boolean});const emit=defineEmits(['saved','close']);
const confirming=ref(props.remove),dialog=ref(null),all=ref([]),draft=ref(null),type=ref('project'),port=ref(3000),busy=ref(false),message=ref('');
onMounted(async()=>{dialog.value.showModal();try{const result=await requestJson('/api/services');all.value=result.servers;const old=all.value.find(s=>s.id===props.serviceId);if(old){draft.value=JSON.parse(JSON.stringify(old));if(old.systemd&&!old.source){draft.value.source=old.systemd.unit;draft.value.sudo=old.systemd.sudo;}if(old.project&&!old.source){const {path,...options}=old.project;draft.value.source=path;draft.value.projectOptions=options;}type.value=draft.value.source?.endsWith('.service')?'systemd':'project';if(old.url){const url=new URL(old.url);port.value=Number(url.port|| (url.protocol==='https:'?443:80));}else port.value=type.value==='systemd'?null:Number(old.projectOptions?.env?.PORT||3000);}else{let n=1;while(all.value.some(s=>s.id==='service-'+n))n++;draft.value={id:'service-'+n,name:'',source:''};}}catch(e){notify(e.message,'error');}});
function payload(){const value={...draft.value};delete value.systemd;delete value.project;delete value.source;delete value.url;
 if(type.value==='systemd'){const name=draft.value.source.trim();value.source=name.endsWith('.service')?name:name+'.service';delete value.projectOptions;if(port.value)value.url='http://127.0.0.1:'+port.value;}
 else{value.source=draft.value.source.trim();value.projectOptions={...(value.projectOptions||{}),env:{...(value.projectOptions?.env||{}),PORT:String(port.value)}};value.url='http://127.0.0.1:'+port.value;delete value.sudo;}
 return value;}
async function submit(remove=false){busy.value=true;message.value='';try{const value=remove?null:payload();let servers=all.value.filter(s=>s.id!==draft.value.id);if(value){servers=all.value.some(s=>s.id===value.id)?all.value.map(s=>s.id===value.id?value:s):[...all.value,value];}await requestJson('/api/services',{method:'POST',body:JSON.stringify({servers})});notify(remove?'服务已移除':props.serviceId?'服务配置已保存':'服务已添加');emit('saved');emit('close');}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
</script>
<template><dialog ref="dialog" class="service-editor-dialog" @cancel="busy ? $event.preventDefault() : $emit('close')"><form @submit.prevent="submit(confirming)"><div class="modal-heading"><h2>{{ confirming?'移除服务':serviceId?'编辑服务':'添加服务' }}</h2><button type="button" class="modal-dismiss secondary" aria-label="取消添加或编辑" :disabled="busy" @click="$emit('close')">×</button></div><p v-if="confirming && draft" class="remove-confirmation">确定移除「{{ draft.name || draft.id }}」吗？</p><template v-if="draft && !confirming"><label class="preference-field">服务名称<input v-model="draft.name" placeholder="可选，自动读取项目名称"></label><label class="preference-field">接入方式<select v-model="type" @change="port=type==='systemd'?null:3000"><option value="project">本地项目</option><option value="systemd">systemd 服务</option></select></label><label v-if="type==='project'" class="preference-field">项目文件夹<input v-model="draft.source" required placeholder="项目所在目录"></label><label v-else class="preference-field">systemd 服务名<input v-model="draft.source" required placeholder="stronghold.service"></label><label class="preference-field">端口<input v-model.number="port" type="number" min="1" max="65535" :required="type!=='systemd'" :placeholder="type==='systemd'?'可选，仅用于游戏健康采样':'3000'"></label><label v-if="type==='systemd'" class="connection-option"><input v-model="draft.sudo" type="checkbox">使用 sudo</label></template><div class="modal-actions"><button v-if="confirming" type="button" class="secondary" :disabled="busy" @click="$emit('close')">取消</button><button type="submit" :class="{'confirm-remove':confirming}" :disabled="busy||!draft">{{ busy?'处理中…':confirming?'确定移除':serviceId?'保存':'添加' }}</button></div></form></dialog></template>
